int read_quant_matrices(MpegEncContext *s, GetBitContext *gb) {
    int i, type, matrix_index;

    for (type = 0; type < 4; type++) {
        if (get_bits1(gb)) { // Check if matrix is present in the bitstream
            if (get_bits_count() + 64 > gb->size_in_bits) {
                return AVERROR_INVALIDDATA; // Not enough bits for matrix
            }

            matrix_index = type * 64;
            for (i = 0; i < 64; i++) {
                s->intra_matrix[matrix_index + i] = get_bits(gb, 8);
            }
        } else {
            // Default matrix used if not present
            // (Assume default is handled by the MPEG context setup)
        }
    }

    // Advance to the next start code
    skip_bits(gb, (gb->size_in_bits - get_bits_count()) % 8);
    align_get_bits(gb);

    return 0;
}

int read_quant_matrices(MpegEncContext *s, GetBitContext *gb) {
    int i, q_matrix_type;
    int intra = get_bits1(gb);
    int chroma = get_bits1(gb);

    if (intra) {
        for (i = 0; i < 64; i++) {
            if (get_remaining_bits(gb, 0) < 8) {
                return AVERROR_INVALIDDATA;
            }
            s->intra_matrix[i] = get_bits8(gb);
        }
    }

    for (q_matrix_type = 1; q_matrix_type <= 3; q_matrix_type++) {
        if ((q_matrix_type == 1 && !intra) ||
            (q_matrix_type == 2 && !intra) ||
            (q_matrix_type == 3 && !chroma)) {
            continue;
        }

        for (i = 0; i < 64; i++) {
            if (get_remaining_bits(gb, 0) < 8) {
                return AVERROR_INVALIDDATA;
            }
            s->matrix[q_matrix_type][i] = get_bits8(gb);
        }
    }

    skip_bits(gb, (get_bits_count(gb) + 7) & ~7);
    skip_to_next_start_code(gb);

    return 0;
}

int read_quant_matrices(MpegEncContext *s, GetBitContext *gb) {
    int i;

    if (get_bits1(gb)) {
        for (i = 0; i < 64; i++)
            s->intra_matrix[i] = get_bits(gb, 8);
    }

    if (get_bits1(gb)) {
        for (i = 0; i < 64; i++)
            s->inter_matrix[i] = get_bits(gb, 8);
    }

    if (get_bits1(gb)) {
        for (i = 0; i < 64; i++)
            s->chroma_intra_matrix[i] = get_bits(gb, 8);
    }

    if (get_bits1(gb)) {
        for (i = 0; i < 64; i++)
            s->chroma_inter_matrix[i] = get_bits(gb, 8);
    }

    if (get_bits_left(gb) < 0)
        return AVERROR_INVALIDDATA;

    skip_bits(gb, get_bits_left(gb) & 0x7);
    return 0;
}

int read_quant_matrices(MpegEncContext *s, GetBitContext *gb) {
    int i, found;
    int matrix[64];
    int index;

    found = 0;
    for (i = 0; i < 64; i++) {
        if (get_bits_left(gb) < 8) {
            return AVERROR_INVALIDDATA;
        }
        matrix[i] = get_bits(gb, 8);
    }

    index = get_bits(gb, 8);
    if (index == 0) {
        memcpy(s->intra_matrix, matrix, sizeof(matrix));
        found = 1;
    } else if (index == 1) {
        memcpy(s->inter_matrix, matrix, sizeof(matrix));
        found = 1;
    } else {
        return AVERROR_INVALIDDATA;
    }

    if (found) {
        skip_bits(gb, 8);
        while (get_bits_left(gb) > 0 && show_bits(gb, 8) != 0x00000001) {
            skip_bits(gb, 8);
        }
    }

    return 0;
}

int read_quant_matrices(MpegEncContext *s, GetBitContext *gb) {
    int load_intra_matrix, load_non_intra_matrix;
    int load_chroma_intra_matrix, load_chroma_non_intra_matrix;
    int i;

    // Check if quantization matrices are present in the bitstream
    if (get_bits_left(gb) < 4)
        return AVERROR_INVALIDDATA;

    load_intra_matrix = get_bits1(gb);
    load_non_intra_matrix = get_bits1(gb);
    load_chroma_intra_matrix = get_bits1(gb);
    load_chroma_non_intra_matrix = get_bits1(gb);

    // Read and store the quantization matrices
    if (load_intra_matrix) {
        for (i = 0; i < 64; i++) {
            if (get_bits_left(gb) < 8)
                return AVERROR_INVALIDDATA;
            s->intra_matrix[i] = get_bits(gb, 8);
        }
    }

    if (load_non_intra_matrix) {
        for (i = 0; i < 64; i++) {
            if (get_bits_left(gb) < 8)
                return AVERROR_INVALIDDATA;
            s->non_intra_matrix[i] = get_bits(gb, 8);
        }
    }

    if (load_chroma_intra_matrix) {
        for (i = 0; i < 64; i++) {
            if (get_bits_left(gb) < 8)
                return AVERROR_INVALIDDATA;
            s->chroma_intra_matrix[i] = get_bits(gb, 8);
        }
    }

    if (load_chroma_non_intra_matrix) {
        for (i = 0; i < 64; i++) {
            if (get_bits_left(gb) < 8)
                return AVERROR_INVALIDDATA;
            s->chroma_non_intra_matrix[i] = get_bits(gb, 8);
        }
    }

    // Advance to the next start code
    skip_bits(gb, 8 - (get_bits_count(gb) & 7));
    skip_bits(gb, 32 - (get_bits_count(gb) & 31));

    return 0;
}
